<script setup lang="ts">
import { computed, ref } from 'vue'
import { CalendarDays, MapPin, Users, Truck, Wrench, FlaskConical, ChevronDown, Search, X } from 'lucide-vue-next'
type Visit = { date: string; location: string; business: string; purpose: string; people: number; status: string; personnel?: string[]; vehicles?: string[]; equipment?: string[]; chemicals?: string[] }
const props = defineProps<{ visits: Visit[] }>()
const expandedVisit = ref<string | null>(null)
const searchQuery = ref('')
const statusFilter = ref('')
const organizationFilter = ref('')
const locationFilter = ref('')
const dateFilter = ref('all')
const today = new Date()
const statusMeta = { Planlanan:{classes:'bg-brand-50 text-brand-600',dot:'bg-brand-500'},'Devam Ediyor':{classes:'bg-warning-50 text-warning-600',dot:'bg-warning-500'},Tamamlandı:{classes:'bg-success-50 text-success-600',dot:'bg-success-500'} } as const
const normalizeDate=(value:string)=>{const parts=value.split('.');return parts.length===3?`${parts[2]}-${parts[1].padStart(2,'0')}-${parts[0].padStart(2,'0')}`:value}
const toDate=(value:string)=>new Date(`${normalizeDate(value)}T00:00:00`)
const organizations=computed(()=>[...new Set(props.visits.map(v=>v.business))])
const locations=computed(()=>[...new Set(props.visits.map(v=>v.location))])
const filteredVisits=computed(()=>{const q=searchQuery.value.trim().toLocaleLowerCase('tr-TR');return props.visits.filter(v=>{const d=toDate(v.date);const text=[v.location,v.business,v.purpose,v.status,...(v.personnel??[])].join(' ').toLocaleLowerCase('tr-TR');if(q&&!text.includes(q))return false;if(statusFilter.value&&v.status!==statusFilter.value)return false;if(organizationFilter.value&&v.business!==organizationFilter.value)return false;if(locationFilter.value&&v.location!==locationFilter.value)return false;if(dateFilter.value==='year'&&d.getFullYear()!==today.getFullYear())return false;if(dateFilter.value==='3m'&&d<new Date(today.getFullYear(),today.getMonth()-2,1))return false;if(dateFilter.value==='6m'&&d<new Date(today.getFullYear(),today.getMonth()-5,1))return false;return true})})
const hasFilters=computed(()=>!!(searchQuery.value||statusFilter.value||organizationFilter.value||locationFilter.value||dateFilter.value!=='all'))
const clearFilters=()=>{searchQuery.value='';statusFilter.value='';organizationFilter.value='';locationFilter.value='';dateFilter.value='all'}
const visitKey=(visit:Visit)=>`${visit.date}-${visit.location}-${visit.business}`
const assetCount=(visit:Visit)=>({vehicles:visit.vehicles?.length??0,equipment:visit.equipment?.length??0,chemicals:visit.chemicals?.length??0})
</script>
<template>
<div>
  <div class="mb-4 rounded-xl border border-gray-100 bg-white p-4"><div class="flex flex-wrap items-center gap-2"><div class="relative min-w-[220px] flex-1"><Search :size="14" class="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"/><input v-model="searchQuery" type="text" placeholder="Ziyaretlerde ara..." class="h-9 w-full rounded-lg border border-gray-200 bg-gray-50 pl-9 pr-3 text-xs text-gray-700 outline-none transition focus:border-brand-300 focus:bg-white"/></div><select v-model="dateFilter" class="h-9 rounded-lg border border-gray-200 bg-white px-3 text-xs text-gray-600 outline-none focus:border-brand-300"><option value="all">Tüm tarihler</option><option value="year">Bu yıl</option><option value="3m">Son 3 ay</option><option value="6m">Son 6 ay</option></select><select v-model="statusFilter" class="h-9 rounded-lg border border-gray-200 bg-white px-3 text-xs text-gray-600 outline-none focus:border-brand-300"><option value="">Tüm durumlar</option><option v-for="status in Object.keys(statusMeta)" :key="status" :value="status">{{ status }}</option></select><select v-model="organizationFilter" class="h-9 max-w-[190px] rounded-lg border border-gray-200 bg-white px-3 text-xs text-gray-600 outline-none focus:border-brand-300"><option value="">Tüm organizasyonlar</option><option v-for="organization in organizations" :key="organization" :value="organization">{{ organization }}</option></select><select v-model="locationFilter" class="h-9 max-w-[190px] rounded-lg border border-gray-200 bg-white px-3 text-xs text-gray-600 outline-none focus:border-brand-300"><option value="">Tüm lokasyonlar</option><option v-for="location in locations" :key="location" :value="location">{{ location }}</option></select><button v-if="hasFilters" type="button" @click="clearFilters" class="inline-flex h-9 items-center gap-1.5 rounded-lg border border-gray-200 px-3 text-xs font-medium text-gray-500 hover:bg-gray-50"><X :size="13"/> Temizle</button></div><div class="mt-3 flex items-center justify-between text-[11px] text-gray-400"><span>{{ filteredVisits.length }} ziyaret gösteriliyor</span><span v-if="hasFilters">Filtreler aktif</span></div></div>
  <div class="overflow-x-auto"><table class="w-full min-w-[980px] text-left"><thead><tr class="border-b border-gray-100 text-xs text-gray-500"><th class="pb-3 font-medium">Tarih</th><th class="pb-3 font-medium">Lokasyon</th><th class="pb-3 font-medium">Organizasyon</th><th class="pb-3 font-medium">Ziyaret Nedeni</th><th class="pb-3 font-medium">Personel</th><th class="pb-3 font-medium">Sahaya Getirilenler</th><th class="pb-3 font-medium">Durum</th></tr></thead><tbody><template v-for="visit in filteredVisits" :key="visitKey(visit)"><tr class="border-b border-gray-100 last:border-0"><td class="py-4"><div class="flex items-center gap-2"><CalendarDays :size="14" class="text-gray-400"/><span class="text-sm font-medium text-gray-800">{{ visit.date }}</span></div></td><td class="py-4"><div class="flex items-center gap-1.5"><MapPin :size="14" class="text-gray-400"/><span class="text-sm text-gray-700">{{ visit.location }}</span></div></td><td class="py-4 text-xs text-gray-500">{{ visit.business }}</td><td class="py-4 text-sm text-gray-600">{{ visit.purpose }}</td><td class="py-4"><button type="button" class="inline-flex items-center gap-2 rounded-lg border border-gray-200 bg-white px-2.5 py-1.5 text-[11px] font-medium text-gray-600 hover:bg-gray-50" @click="expandedVisit=expandedVisit===`${visitKey(visit)}:personnel`?null:`${visitKey(visit)}:personnel`"><Users :size="13"/><span>{{ visit.personnel?.length ?? visit.people }} personel</span><ChevronDown :size="13" :class="expandedVisit===`${visitKey(visit)}:personnel`?'rotate-180':''" class="transition-transform"/></button></td><td class="py-4"><button type="button" class="inline-flex items-center gap-2 rounded-lg border border-gray-200 bg-white px-2.5 py-1.5 text-[11px] font-medium text-gray-600 hover:bg-gray-50" @click="expandedVisit=expandedVisit===visitKey(visit)?null:visitKey(visit)"><span class="inline-flex items-center gap-1"><Truck :size="13"/>{{ assetCount(visit).vehicles }}</span><span class="inline-flex items-center gap-1"><Wrench :size="13"/>{{ assetCount(visit).equipment }}</span><span class="inline-flex items-center gap-1"><FlaskConical :size="13"/>{{ assetCount(visit).chemicals }}</span><ChevronDown :size="13" :class="expandedVisit===visitKey(visit)?'rotate-180':''" class="transition-transform"/></button></td><td class="py-4"><span class="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-medium" :class="statusMeta[visit.status as keyof typeof statusMeta]?.classes||'bg-gray-100 text-gray-500'"><span class="h-1.5 w-1.5 rounded-full" :class="statusMeta[visit.status as keyof typeof statusMeta]?.dot||'bg-gray-400'"/>{{ visit.status }}</span></td></tr><tr v-if="expandedVisit===`${visitKey(visit)}:personnel`" class="border-b border-gray-100 bg-gray-50/60"><td colspan="7" class="px-4 py-4"><div class="flex flex-wrap gap-2"><span v-for="person in (visit.personnel??Array.from({length:visit.people},(_,i)=>`Personel ${i+1}`))" :key="person" class="rounded-full bg-white px-3 py-1.5 text-[11px] font-medium text-gray-600 border border-gray-200">{{ person }}</span></div></td></tr><tr v-if="expandedVisit===visitKey(visit)" class="border-b border-gray-100 bg-gray-50/60"><td colspan="7" class="px-4 py-4"><div class="grid gap-3 md:grid-cols-3"><div><p class="text-[11px] font-semibold text-gray-500">Araçlar</p><p class="mt-1 text-xs text-gray-700">{{ visit.vehicles?.join(', ') || 'Yok' }}</p></div><div><p class="text-[11px] font-semibold text-gray-500">Ekipmanlar</p><p class="mt-1 text-xs text-gray-700">{{ visit.equipment?.join(', ') || 'Yok' }}</p></div><div><p class="text-[11px] font-semibold text-gray-500">Kimyasallar</p><p class="mt-1 text-xs text-gray-700">{{ visit.chemicals?.join(', ') || 'Yok' }}</p></div></div></td></tr></template><tr v-if="!filteredVisits.length"><td colspan="7" class="py-12 text-center text-xs text-gray-500">Filtrelere uygun saha ziyareti bulunmuyor.</td></tr></tbody></table></div>
</div>
</template>